prompt:
Create unit `tasks` and implement `all_nonneg`: true exactly when every element of `a` is >= 0. The contract must state that equivalence.

Required signature (in unit `tasks`):
fn all_nonneg(a: &[i64]) -> (r: bool)

reference.code:
spec fn nonneg_below(a: &[i64], n: usize) -> bool { forall|k: usize| k < n ==> #[trigger] a[k] >= 0 }

spec fn all_nonneg_spec(a: &[i64], r: bool) -> bool { r == (forall|k: usize| k < a.len() ==> #[trigger] a[k] >= 0) }

#[effects(pure)]
#[uses(nonneg_below, all_nonneg_spec)]
fn all_nonneg(a: &[i64]) -> (r: bool)
    ensures all_nonneg_spec(a, r),
{
    let mut k: usize = 0;
    while k < a.len() && a[k] >= 0
        invariant k <= a.len(), nonneg_below(a, k),
        decreases a.len() - k,
    {
        k = k + 1;
    }
    k == a.len()
}
